const CHAT_SVG=svg('<rect x="70" y="14" width="112" height="46" rx="16" fill="'+NV+'" stroke="'+BL+'" stroke-width="2"/><path d="M92 60l-4 16 20-16z" fill="'+NV+'" stroke="'+BL+'" stroke-width="2" stroke-linejoin="round"/><circle cx="102" cy="37" r="5" fill="'+LB+'"/><circle cx="126" cy="37" r="5" fill="'+LB+'"/><circle cx="150" cy="37" r="5" fill="'+LB+'"/><rect x="168" y="38" width="66" height="38" rx="14" fill="url(#gO)"/><path d="M214 76l6 12 6-12z" fill="#ff7a2f"/><path d="M184 57h34M184 66h22" stroke="#1b0d02" stroke-opacity=".6" stroke-width="3.5" stroke-linecap="round"/>');
