 +'<p style="white-space:pre-wrap">'+esc(t.desc)+'</p><div class="kv"><span>Task ID</span><b>'+tcode(t.id)+'</b></div><div class="kv"><span>Slots left</span><b>'+Math.max(0,left(t))+'</b></div><div class="kv"><span>Screenshots required</span><b>'+t.shots+'</b></div><div class="kv"><span>Task price</span><b>'+usdp(t.price)+' <span class="mut">(you get '+usdp(net(t.price))+')</span></b></div><div class="kv"><span>Time left</span><b>'+dleft(t)+'</b></div><div class="kv"><span>Link</span><a class="lnk" href="'+esc(t.link)+'" target="_blank" rel="noopener noreferrer">Open task link ↗</a></div></div>'+exCard(t)
