 const ty=typeOf(s,f.tid)||{name:'Task',id:f.tid};const shots=f.shots||1;const min=minFor(s,f.tid,f.mins,shots);const price=f.price!=null?f.price:min;const w=f.w||s.workerOpts[0];const days=f.days||s.dayOpts[0];
 F.shots=shots;F.price=price;F.w=w;F.days=days;const tot=taskCost(s,price||0,w,days,f.boost,f.top);
 return head('Create task')+'<div class="pg"><div class="card"><div class="row"><div style="flex:1"><b>'+esc(f.cat)+' · '+esc(ty.name)+(f.mins?' · '+f.mins+' min':'')+'</b></div><button class="btn sm out" data-a="fback">Change</button></div></div><div class="card"><label class="lb" style="margin-top:0">Title</label><input class="in" data-f="title" maxlength="80" value="'+esc(f.title||'')+'" placeholder="e.g. Subscribe to my channel"><label class="lb">Description</label><textarea class="in" data-f="desc" maxlength="500" placeholder="What should the worker do?">'+esc(f.desc||'')+'</textarea>'
